 body text;
BEGIN
 SELECT string_agg(coalesce(dictionary->>piece[1],piece[1]),'' ORDER BY ord)
 INTO body FROM regexp_matches(packed,'~A[0-9]+~|[^~]+|~','g')
 WITH ORDINALITY AS fragments(piece,ord);
 IF encode(sha256(convert_to(body,'UTF8')),'hex') <> '6d194c8d6dc67c0417ceeb6d20b7357f5d6617637596b492685ef60528f142e8' THEN
  RAISE EXCEPTION 'Reference payload reconstruction failed hash verification';
 END IF;
 VALUES ('b6ff93ae-3210-5bbe-8410-a3f6d989962a','6d194c8d6dc67c0417ceeb6d20b7357f5d6617637596b492685ef60528f142e8',body,body::jsonb)
 ON CONFLICT(id) DO NOTHING;
 IF NOT EXISTS (SELECT 1 FROM asgard_catalog.occupational_releases
   WHERE id='b6ff93ae-3210-5bbe-8410-a3f6d989962a' AND canonical_payload=body
   AND sha256='6d194c8d6dc67c0417ceeb6d20b7357f5d6617637596b492685ef60528f142e8') THEN
  RAISE EXCEPTION 'Conflicting existing occupational release';
 END IF;
END$asgard_data_$;
