INSERT INTO asgard_catalog.esco_concepts(release_id,uri,kind,label,alternatives,description) SELECT '8e4deef5-ac7a-5960-b937-8a98e34803a6'::uuid, 'http://data.europa.eu/esco/skill/0da6cab1-0ee9-4391-a299-f71fbf21db56', 'skill', 'ICT network routing', ARRAY[]::text[], 'The processes and techniques for choosing the best paths within an ICT network through which a packet can travel.' WHERE EXISTS (SELECT 1 FROM asgard_catalog.esco_releases WHERE id='8e4deef5-ac7a-5960-b937-8a98e34803a6' AND NOT sealed) ON CONFLICT DO NOTHING;
