INSERT INTO asgard_catalog.esco_concepts(release_id,uri,kind,label,alternatives,description) SELECT '8e4deef5-ac7a-5960-b937-8a98e34803a6'::uuid, 'http://data.europa.eu/esco/skill/2164e860-7f20-48bc-b98c-5d9f8a561550', 'skill', 'design computer network', ARRAY[]::text[], 'Develop and plan ICT networks, such as wide area network and local area network, that connect computers using cable or wireless connections and allow them to exchange data and assess their capacity requirements.' WHERE EXISTS (SELECT 1 FROM asgard_catalog.esco_releases WHERE id='8e4deef5-ac7a-5960-b937-8a98e34803a6' AND NOT sealed) ON CONFLICT DO NOTHING;
INSERT INTO asgard_catalog.esco_concepts(release_id,uri,kind,label,alternatives,description) SELECT '8e4deef5-ac7a-5960-b937-8a98e34803a6'::uuid, 'http://data.europa.eu/esco/skill/2180bd8c-86de-4889-8165-adac902eee9d', 'skill', 'embedded systems', ARRAY[]::text[], 'The computer systems and components with a specialised and autonomous function within a larger system or machine such as embedded systems software architectures, embedded peripherals, design principles and development tools.' WHERE EXISTS (SELECT 1 FROM asgard_catalog.esco_releases WHERE id='8e4deef5-ac7a-5960-b937-8a98e34803a6' AND NOT sealed) ON CONFLICT DO NOTHING;
INSERT INTO asgard_catalog.esco_concepts(release_id,uri,kind,label,alternatives,description) SELECT '8e4deef5-ac7a-5960-b937-8a98e34803a6'::uuid, 'http://data.europa.eu/esco/skill/2522a6ce-3202-4ac8-9f5b-b9cb5a3a83a1', 'skill', 'debug software', ARRAY[]::text[], 'Repair computer code by analysing testing results, locating the defects causing the software to output an incorrect or unexpected result and remove these faults.' WHERE EXISTS (SELECT 1 FROM asgard_catalog.esco_releases WHERE id='8e4deef5-ac7a-5960-b937-8a98e34803a6' AND NOT sealed) ON CONFLICT DO NOTHING;
INSERT INTO asgard_catalog.esco_concepts(release_id,uri,kind,label,alternatives,description) SELECT '8e4deef5-ac7a-5960-b937-8a98e34803a6'::uuid, 'http://data.europa.eu/esco/skill/2d6d4784-0992-48e7-b100-22d7229b3f0a', 'skill', 'translate requirements into visual design', ARRAY[]::text[], 'Develop visual design from given specifications and requirements, based on the analysis of the scope and target audience. Create a visual representation of ideas such as logos, website graphics, digital games and layouts.' WHERE EXISTS (SELECT 1 FROM asgard_catalog.esco_releases WHERE id='8e4deef5-ac7a-5960-b937-8a98e34803a6' AND NOT sealed) ON CONFLICT DO NOTHING;
INSERT INTO asgard_catalog.esco_concepts(release_id,uri,kind,label,alternatives,description) SELECT '8e4deef5-ac7a-5960-b937-8a98e34803a6'::uuid, 'http://data.europa.eu/esco/skill/382c11ed-20d5-4ae7-b60e-15fec527fa6c', 'skill', 'apply statistical analysis techniques', ARRAY[]::text[], 'Use models (descriptive or inferential statistics) and techniques (data mining or machine learning) for statistical analysis and ICT tools to analyse data, uncover correlations and forecast trends.' WHERE EXISTS (SELECT 1 FROM asgard_catalog.esco_releases WHERE id='8e4deef5-ac7a-5960-b937-8a98e34803a6' AND NOT sealed) ON CONFLICT DO NOTHING;
INSERT INTO asgard_catalog.esco_concepts(release_id,uri,kind,label,alternatives,description) SELECT '8e4deef5-ac7a-5960-b937-8a98e34803a6'::uuid, 'http://data.europa.eu/esco/skill/440d5784-52a5-4729-8b04-29f978bd896d', 'skill', 'respond to incidents in cloud', ARRAY[]::text[], '' WHERE EXISTS (SELECT 1 FROM asgard_catalog.esco_releases WHERE id='8e4deef5-ac7a-5960-b937-8a98e34803a6' AND NOT sealed) ON CONFLICT DO NOTHING;
INSERT INTO asgard_catalog.esco_concepts(release_id,uri,kind,label,alternatives,description) SELECT '8e4deef5-ac7a-5960-b937-8a98e34803a6'::uuid, 'http://data.europa.eu/esco/skill/4d85b881-e490-4b4c-897a-2faa4ef53956', 'skill', 'manage ICT data architecture', ARRAY[]::text[], 'Oversee regulations and use ICT techniques to define the information systems architecture and to control data gathering, storing, consolidation, arrangement and usage in an organisation.' WHERE EXISTS (SELECT 1 FROM asgard_catalog.esco_releases WHERE id='8e4deef5-ac7a-5960-b937-8a98e34803a6' AND NOT sealed) ON CONFLICT DO NOTHING;
INSERT INTO asgard_catalog.esco_concepts(release_id,uri,kind,label,alternatives,description) SELECT '8e4deef5-ac7a-5960-b937-8a98e34803a6'::uuid, 'http://data.europa.eu/esco/skill/4da4587a-fd0b-4ca2-886c-c42a1562d432', 'skill', 'design cloud networks', ARRAY[]::text[], '' WHERE EXISTS (SELECT 1 FROM asgard_catalog.esco_releases WHERE id='8e4deef5-ac7a-5960-b937-8a98e34803a6' AND NOT sealed) ON CONFLICT DO NOTHING;
INSERT INTO asgard_catalog.esco_concepts(release_id,uri,kind,label,alternatives,description) SELECT '8e4deef5-ac7a-5960-b937-8a98e34803a6'::uuid, 'http://data.europa.eu/esco/skill/501537a7-9d63-491d-ae02-09f04767ff1e', 'skill', 'attack vectors', ARRAY[]::text[], 'Paths or methods that threat actors use to exploit vulnerabilities in information networks or systems from a concrete organisation and impact its availability, integrity and confidentiality. Attack vectors may include social engineering tactics such as phishing mails or pretexting, technical exploits as SQL injection as well as buffer overflow attacks.' WHERE EXISTS (SELECT 1 FROM asgard_catalog.esco_releases WHERE id='8e4deef5-ac7a-5960-b937-8a98e34803a6' AND NOT sealed) ON CONFLICT DO NOTHING;
INSERT INTO asgard_catalog.esco_concepts(release_id,uri,kind,label,alternatives,description) SELECT '8e4deef5-ac7a-5960-b937-8a98e34803a6'::uuid, 'http://data.europa.eu/esco/skill/50b100ea-74fd-4706-99db-3e4ca55e51b8', 'skill', 'perform data cleansing', ARRAY[]::text[], 'Detect and correct corrupt records from data sets, ensure that the data become and remain structured according to guidelines.' WHERE EXISTS (SELECT 1 FROM asgard_catalog.esco_releases WHERE id='8e4deef5-ac7a-5960-b937-8a98e34803a6' AND NOT sealed) ON CONFLICT DO NOTHING;
INSERT INTO asgard_catalog.esco_concepts(release_id,uri,kind,label,alternatives,description) SELECT '8e4deef5-ac7a-5960-b937-8a98e34803a6'::uuid, 'http://data.europa.eu/esco/skill/52b38e90-3d05-4042-a9e2-d19dec8dd7c1', 'skill', 'test hardware', ARRAY[]::text[], 'Test computer hardware systems and components using appropriate equipment and testing methods, such as the system test (ST), the ongoing reliability test (ORT), and the in-circuit test (ICT). Monitor and evaluate system performance and take action if needed.' WHERE EXISTS (SELECT 1 FROM asgard_catalog.esco_releases WHERE id='8e4deef5-ac7a-5960-b937-8a98e34803a6' AND NOT sealed) ON CONFLICT DO NOTHING;
INSERT INTO asgard_catalog.esco_concepts(release_id,uri,kind,label,alternatives,description) SELECT '8e4deef5-ac7a-5960-b937-8a98e34803a6'::uuid, 'http://data.europa.eu/esco/skill/545c80e8-7ab2-42fe-af64-242211e94709', 'skill', 'analyse network configuration and performance', ARRAY[]::text[], 'Analyse essential network data (e.g., router configuration files, routing protocols), network traffic capacity and performance characteristics of ICT networks, such as wide area network and local area network, that connect computers using cable or wireless connections and allow them to exchange data.' WHERE EXISTS (SELECT 1 FROM asgard_catalog.esco_releases WHERE id='8e4deef5-ac7a-5960-b937-8a98e34803a6' AND NOT sealed) ON CONFLICT DO NOTHING;
INSERT INTO asgard_catalog.esco_concepts(release_id,uri,kind,label,alternatives,description) SELECT '8e4deef5-ac7a-5960-b937-8a98e34803a6'::uuid, 'http://data.europa.eu/esco/skill/5608d5a0-6d5e-43b7-be37-616501729bb4', 'skill', 'artificial neural networks', ARRAY[]::text[], 'A network of artificial neurons composed for solving artificial intelligence problems. These computing systems are inspired by the biological neural networks that constitute brains. Understanding of its general model and its elements. Knowledge of its use possibilities for automation.' WHERE EXISTS (SELECT 1 FROM asgard_catalog.esco_releases WHERE id='8e4deef5-ac7a-5960-b937-8a98e34803a6' AND NOT sealed) ON CONFLICT DO NOTHING;
INSERT INTO asgard_catalog.esco_concepts(release_id,uri,kind,label,alternatives,description) SELECT '8e4deef5-ac7a-5960-b937-8a98e34803a6'::uuid, 'http://data.europa.eu/esco/skill/5898d99a-62a4-4e10-a2e3-0d815ce44248', 'skill', 'cyber attack counter-measures', ARRAY[]::text[], 'Methods, technologies and techniques used to defend (detect, monitor and recover) against cyber attacks. These cyber attacks include several attack vectors such as malware, denial of service (DoS) attacks and phishing. Intrusion prevention systems (IPS), firewall, antivirus, intrusion detection systems (IDS), cybersecurity training, backup, Information Security Management System (ISM), multi-factor authentication and employ awareness, are some examples of the methods used.' WHERE EXISTS (SELECT 1 FROM asgard_catalog.esco_releases WHERE id='8e4deef5-ac7a-5960-b937-8a98e34803a6' AND NOT sealed) ON CONFLICT DO NOTHING;
INSERT INTO asgard_catalog.esco_concepts(release_id,uri,kind,label,alternatives,description) SELECT '8e4deef5-ac7a-5960-b937-8a98e34803a6'::uuid, 'http://data.europa.eu/esco/skill/6195c5f7-a4fb-425d-a3dd-c4467c4471a3', 'skill', 'deploy cloud resource', ARRAY[]::text[], 'Identify and execute steps required to provision cloud resources, such as networks, servers, storage, applications, GPUs, and services. Define the cloud global infrastructure and remediate deployment issues.' WHERE EXISTS (SELECT 1 FROM asgard_catalog.esco_releases WHERE id='8e4deef5-ac7a-5960-b937-8a98e34803a6' AND NOT sealed) ON CONFLICT DO NOTHING;
INSERT INTO asgard_catalog.esco_concepts(release_id,uri,kind,label,alternatives,description) SELECT '8e4deef5-ac7a-5960-b937-8a98e34803a6'::uuid, 'http://data.europa.eu/esco/skill/65e58886-bd1e-4c5b-8ca5-8d9b353c8aa1', 'skill', 'data visualisation software', ARRAY[]::text[], '' WHERE EXISTS (SELECT 1 FROM asgard_catalog.esco_releases WHERE id='8e4deef5-ac7a-5960-b937-8a98e34803a6' AND NOT sealed) ON CONFLICT DO NOTHING;
